INSERT INTO "PetPost" (
    "authorId", title, content, "createdAt", "updatedAt"
) VALUES
('00000000-0000-0000-0000-000000000001', '우리 강아지 첫 산책 후기', '오늘 처음으로 동네 공원에 산책을 다녀왔어요. 처음엔 낯설어했는데 금방 적응해서 신나게 뛰어다녔습니다. 다음엔 좀 더 멀리 나가볼 예정이에요.', now() - interval '40 days', now() - interval '40 days'),
('00000000-0000-0000-0000-000000000002', '고양이 낮잠 자는 모습 공유합니다', '햇살 좋은 창가에서 늘어지게 자는 모습이 너무 귀여워서 사진 찍어봤어요. 하루의 대부분을 자면서 보내는데 그게 또 매력이더라고요.', now() - interval '38 days', now() - interval '38 days'),
('00000000-0000-0000-0000-000000000003', '입양한 지 한 달 된 강아지 근황', '입양 초기엔 겁이 많아서 숨어만 있었는데, 이제는 꼬리도 흔들고 애교도 부려요. 가족이 되어줘서 정말 고맙습니다.', now() - interval '36 days', now() - interval '36 days'),
('00000000-0000-0000-0000-000000000004', '반려묘 건강검진 다녀왔어요', '정기 건강검진에서 다행히 모두 정상이라는 결과를 받았습니다. 스트레스 받을까봐 걱정했는데 순하게 잘 참아줬어요.', now() - interval '34 days', now() - interval '34 days'),
('00000000-0000-0000-0000-000000000005', '강아지 목욕 시키는 팁 공유', '물을 무서워하는 강아지도 천천히 적응시키면 괜찮아지더라고요. 미온수 사용하고 칭찬을 많이 해주는 게 도움이 됐습니다.', now() - interval '32 days', now() - interval '32 days'),
('00000000-0000-0000-0000-000000000001', '유기묘 임시보호 시작합니다', '길에서 발견한 아기 고양이를 임시보호하게 되었어요. 건강 상태는 양호하고 사람 손도 잘 타는 편입니다. 좋은 가족 찾아주고 싶어요.', now() - interval '30 days', now() - interval '30 days'),
('00000000-0000-0000-0000-000000000002', '강아지와 함께한 캠핑 후기', '처음으로 반려견 동반 캠핑장에 다녀왔는데 정말 좋아하더라고요. 자연 속에서 뛰어노는 모습 보니 뿌듯했습니다.', now() - interval '27 days', now() - interval '27 days'),
('00000000-0000-0000-0000-000000000003', '고양이 사료 바꾼 후 변화', '기존 사료에서 새 사료로 바꾼 뒤로 털에 윤기가 더 나는 것 같아요. 소화도 잘 되는지 활동량도 늘었습니다.', now() - interval '25 days', now() - interval '25 days'),
('00000000-0000-0000-0000-000000000004', '반려견 훈련소 다녀온 후기', '기본 명령어 교육을 받으러 다녀왔는데 확실히 집중력이 좋아졌어요. 앉아, 기다려는 이제 완벽하게 해냅니다.', now() - interval '23 days', now() - interval '23 days'),
('00000000-0000-0000-0000-000000000005', '고양이 캣타워 조립 완료', '드디어 캣타워를 조립해서 거실에 놔줬는데, 바로 꼭대기까지 올라가서 자리 잡고 있네요. 반응이 좋아서 다행입니다.', now() - interval '21 days', now() - interval '21 days'),
('00000000-0000-0000-0000-000000000001', '강아지 예방접종 완료했어요', '올해 접종 일정을 모두 마쳤습니다. 병원 가는 걸 무서워해서 걱정했는데 간식 덕분에 잘 견뎌줬어요.', now() - interval '19 days', now() - interval '19 days'),
('00000000-0000-0000-0000-000000000002', '유기견 보호소 봉사활동 다녀왔습니다', '주말에 근처 보호소에서 산책 봉사를 하고 왔어요. 아이들이 사람 손길을 그리워하는 게 느껴져서 마음이 아팠습니다.', now() - interval '16 days', now() - interval '16 days'),
('00000000-0000-0000-0000-000000000003', '고양이 스크래처 추천해요', '여러 제품을 써봤는데 마 소재 스크래처를 가장 좋아하더라고요. 가구 긁는 습관도 많이 줄었습니다.', now() - interval '14 days', now() - interval '14 days'),
('00000000-0000-0000-0000-000000000004', '반려동물 동반 카페 다녀온 후기', '넓은 마당이 있는 카페였는데 강아지가 자유롭게 뛰어놀 수 있어서 좋았어요. 다른 강아지들과도 잘 어울렸습니다.', now() - interval '12 days', now() - interval '12 days'),
('00000000-0000-0000-0000-000000000005', '입양 절차 진행 중 후기', '서류 준비하고 상담받는 과정이 생각보다 꼼꼼해서 놀랐어요. 그만큼 신중하게 진행되는 것 같아 안심이 됐습니다.', now() - interval '10 days', now() - interval '10 days'),
('00000000-0000-0000-0000-000000000001', '강아지 치아 관리 방법 공유', '매일 양치질 시키는 게 쉽지 않았는데, 치약을 좋아하는 맛으로 바꾸니 훨씬 수월해졌어요.', now() - interval '8 days', now() - interval '8 days'),
('00000000-0000-0000-0000-000000000002', '고양이 중성화 수술 후기', '수술 후 회복 기간 동안 넥카라를 답답해했지만 일주일 정도 지나니 잘 적응했어요. 지금은 활발하게 잘 지내고 있습니다.', now() - interval '6 days', now() - interval '6 days'),
('00000000-0000-0000-0000-000000000003', '반려견 미용 다녀왔어요', '여름이라 짧게 미용했는데 훨씬 시원해 보이고 활동적으로 변했어요. 미용사님이 순하게 잘 봐주셨습니다.', now() - interval '4 days', now() - interval '4 days'),
('00000000-0000-0000-0000-000000000004', '고양이와 강아지 합사 과정', '처음엔 서로 경계했는데 2주 정도 지나니 같은 공간에서 편하게 지내네요. 천천히 적응시키는 게 중요한 것 같아요.', now() - interval '2 days', now() - interval '2 days'),
('00000000-0000-0000-0000-000000000005', '유기동물 후원 캠페인 참여 후기', '작은 금액이지만 정기 후원을 시작했습니다. 보호소 소식지를 받아보니 도움이 되고 있다는 게 느껴져서 뿌듯합니다.', now(), now());